// src/screens/HomeScreen.tsx
import React, { useEffect, useMemo, useState } from 'react';
import {
  ScrollView,
  View,
  Text,
  TouchableOpacity,
  Image,
  StyleSheet,
  LayoutChangeEvent,
} from 'react-native';
import { useSettings } from '../store/useSettings';
import { getAllChapters } from '../lib/dataSource';
import type { Chapter } from '../store/useCustomData';

/**
 * Objectifs :
 * - 4 vignettes par ligne quand la place le permet, sinon 3/2/1.
 * - Les vignettes remplissent la largeur disponible.
 * - Toutes les vignettes d’un groupe ont la même largeur ET la même hauteur.
 * - Revenir à une hauteur "compacte" (comme avant).
 *
 * Implémentation :
 * - On calcule le nombre de colonnes et la largeur de base.
 * - On rend des lignes « chunkées » (pas de flexWrap) pour maitriser le passage à la ligne.
 * - On répartit le reste de pixels (arrondis) sur les 1ers items de chaque ligne afin d’occuper 100% de la largeur.
 */

const GAP = 12;             // espace horizontal/vertical entre vignettes
const PADDING_H = 16;       // padding horizontal du container
const MAX_COLS = 4;         // on cible 4 colonnes max
const MIN_CARD_WIDTH = 200; // largeur mini lisible

const IMG_HEIGHT = 80;      // image compacte "comme avant"
const TITLE_HEIGHT = 52;    // bandeau titre (fixe) -> hauteur uniforme

type Grid = { cols: number; cardW: number; remainder: number };

function computeGrid(containerWidth: number): Grid {
  const inner = Math.max(0, containerWidth - 2 * PADDING_H);
  for (let cols = MAX_COLS; cols >= 1; cols--) {
    const totalGaps = GAP * (cols - 1);
    const base = Math.floor((inner - totalGaps) / cols);
    if (base >= MIN_CARD_WIDTH) {
      const used = base * cols + totalGaps;
      const remainder = Math.max(0, inner - used); // < cols
      return { cols, cardW: base, remainder };
    }
  }
  // Fallback
  return { cols: 1, cardW: inner, remainder: 0 };
}

function chunk<T>(arr: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

export default function HomeScreen({ navigation }: any) {
  const [chapters, setChapters] = useState<Chapter[]>([]);
  const selectedCursus = useSettings(s => s.selectedCursus);
  const themeColor = useSettings(s => s.themeColor);

  useEffect(() => {
    (async () => {
      const ch = await getAllChapters();
      setChapters(ch);
    })();
  }, []);

  // grille responsive
  const [grid, setGrid] = useState<Grid>({ cols: 1, cardW: 320, remainder: 0 });
  const onLayout = (e: LayoutChangeEvent) => {
    setGrid(computeGrid(e.nativeEvent.layout.width));
  };

  // Filtrer selon les cursus sélectionnés
  const filtered = useMemo(
    () =>
      chapters.filter(
        ch => selectedCursus.size === 0 || selectedCursus.has(ch.cursus_code)
      ),
    [chapters, selectedCursus]
  );

  // Regrouper par cursus et trier
  const groups = useMemo(() => {
    const map: Record<string, Chapter[]> = {};
    for (const ch of filtered) {
      if (!map[ch.cursus_code]) map[ch.cursus_code] = [];
      map[ch.cursus_code].push(ch);
    }
    Object.values(map).forEach(list =>
      list.sort((a, b) => {
        const sa = a.sort_index ?? 1e9;
        const sb = b.sort_index ?? 1e9;
        if (sa !== sb) return sa - sb;
        return a.title.localeCompare(b.title);
      })
    );
    return Object.entries(map).sort((a, b) => a[0].localeCompare(b[0]));
  }, [filtered]);

  return (
    <ScrollView contentContainerStyle={styles.container} onLayout={onLayout}>
      <Text style={styles.h1}>Chapitres</Text>

      {groups.map(([cursusCode, list]) => {
        const rows = chunk(list, grid.cols);
        return (
          <View key={cursusCode} style={styles.section}>
            <Text style={styles.cursusTitle}>{cursusCode}</Text>

            {rows.map((row, rIndex) => (
              <View key={`${cursusCode}-row-${rIndex}`} style={styles.row}>
                {row.map((ch, j) => {
                  // Répartir les pixels "restants" pour remplir la ligne
                  const extra = j < grid.remainder ? 1 : 0;
                  const isLast = j === row.length - 1;
                  return (
                    <TouchableOpacity
                      key={ch.id}
                      style={[
                        styles.card,
                        {
                          width: grid.cardW + extra,
                          borderColor: themeColor,
                          marginRight: isLast ? 0 : GAP
                        }
                      ]}
                      onPress={() => navigation.navigate('Chapter', { chapter: ch })}
                    >
                      <View style={styles.imgWrap}>
                        {ch.cover_url ? (
                          <Image source={{ uri: ch.cover_url }} style={styles.img} resizeMode="cover" />
                        ) : (
                          <View style={[styles.img, { alignItems:'center', justifyContent:'center' }]}>
                            <Text style={{ color:'#999' }}>Sans image</Text>
                          </View>
                        )}
                      </View>
                      <View style={styles.titleWrap}>
                        <Text style={styles.title} numberOfLines={2} ellipsizeMode="tail">
                          {ch.title}
                        </Text>
                      </View>
                    </TouchableOpacity>
                  );
                })}
              </View>
            ))}
          </View>
        );
      })}

      <View style={{ height: 24 }} />
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { paddingTop: 16, paddingBottom: 24 },
  h1: { fontSize: 22, fontWeight: '700', marginHorizontal: 16, marginBottom: 12 },

  section: { marginBottom: 16 },
  cursusTitle: { fontSize: 18, fontWeight: '700', marginHorizontal: 16, marginBottom: 8 },

  // Chaque ligne est un conteneur sans flexWrap (on contrôle nous-même les retours à la ligne)
  row: {
    flexDirection: 'row',
    paddingHorizontal: PADDING_H,
    marginBottom: GAP
  },

  // Cartes compactes et uniformes
  card: {
    borderRadius: 16,
    borderWidth: 2,
    backgroundColor: '#fff',
    overflow: 'hidden',
    alignItems: 'center',
    justifyContent: 'center'
  },
  imgWrap: { width: '100%', height: IMG_HEIGHT, backgroundColor: '#fafafa' },
  img: { width: '100%', height: '100%' },

  titleWrap: {
    width: '100%',
    height: TITLE_HEIGHT,
    paddingHorizontal: 8,
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: '#fff'
  },
  title: { textAlign: 'center', width: '100%', flexWrap: 'wrap' }
});
